class Solution:
    def minOperations(self, n: int) -> int:
        from functools import lru_cache
        @lru_cache(None)
        def f(x):
            if x == 0: return 0
            if x % 2 == 0: return f(x // 2)
            return 1 + min(f(x - 1), f(x + 1))
        return f(n)

