class Solution {
    unordered_map<long long,int> memo;
public:
    int f(long long x) {
        if (x == 0) return 0;
        if (x % 2 == 0) return f(x / 2);
        auto it = memo.find(x);
        if (it != memo.end()) return it->second;
        int r = 1 + min(f(x - 1), f(x + 1));
        memo[x] = r;
        return r;
    }
    int minOperations(int n) { return f(n); }
};

