        if (x == 0) return 0;
        if (x % 2 == 0) return f(x / 2);
        Integer m = memo.get(x);
        if (m != null) return m;
        int r = 1 + Math.min(f(x - 1), f(x + 1));
        memo.put(x, r);
        return r;
    }
    public int minOperations(int n) { return f(n); }
}

