public:
    int minOperations(int n) {
        int ans = 0;
        long long x = n;
        while (x) {
            if (x & 1) {
                if ((x & 3) == 3) x++;
                else x--;
                ans++;
            } else x >>= 1;
        }
        return ans;
    }
};

